Aşağıdaki JavaScript modülünü incele ve gerçek hataları (yanlış sonuç, çökme, sonsuz döngü, beklenmeyen yan etki) satır numarasıyla bildir. Her hatayı en belirgin olduğu tek satırla bildir.

İzin verilen türler: `sinir_hatasi`, `yanlis_kosul`, `yan_etki`, `async_hata`, `yanlis_varsayilan`, `kapsam_hatasi`, `null_kontrolu`, `tip_hatasi`.
Cevabının sonunda YALNIZCA gerçek sorunları içeren tek bir ```json bloğu ver: [{"satir": satır_numarası, "tur": "tür"}, ...]. Sorun olmayan satırları bildirme; yanlış alarmlar puan kırar.

```javascript
  1| // Sipariş yardımcıları (Node.js)
  2| 
  3| function sonNEleman(dizi, n) {
  4|   const sonuc = [];
  5|   for (let i = dizi.length - n; i <= dizi.length; i++) sonuc.push(dizi[i]);
  6|   return sonuc;
  7| }
  8| 
  9| function stoktaVarMi(urunler, ad) {
 10|   return urunler.map((u) => u.ad).indexOf(ad) > 0;
 11| }
 12| 
 13| function enPahalilar(urunler, k = 3) {
 14|   return urunler.sort((a, b) => b.fiyat - a.fiyat).slice(0, k);
 15| }
 16| 
 17| async function fiyatlariGetir(idler, getir) {
 18|   const fiyatlar = {};
 19|   idler.forEach(async (id) => {
 20|     fiyatlar[id] = await getir(id);
 21|   });
 22|   return fiyatlar;
 23| }
 24| 
 25| function sayfala(liste, boyut = 0) {
 26|   const sayfalar = [];
 27|   for (let i = 0; i < liste.length; i += boyut) sayfalar.push(liste.slice(i, i + boyut));
 28|   return sayfalar;
 29| }
 30| 
 31| function zamanlayicilar(isler) {
 32|   for (var i = 0; i < isler.length; i++) {
 33|     setTimeout(() => isler[i].calistir(), 10);
 34|   }
 35| }
 36| 
 37| function sehir(kullanici) {
 38|   // kullanici.adres isteğe bağlıdır (bazı kullanıcılarda hiç yoktur)
 39|   return kullanici.adres.sehir.toUpperCase();
 40| }
 41| 
 42| function toplamTutar(sepet) {
 43|   return sepet.reduce((t, k) => t + k.fiyat * k.adet, 0);
 44| }
 45| 
 46| module.exports = { sonNEleman, stoktaVarMi, enPahalilar, fiyatlariGetir, sayfala, zamanlayicilar, sehir, toplamTutar };
```
